INSERT INTO "public"."email_templates" ("key", "name", "subject", "html_body", "variables", "enabled", "updated_at", "updated_by") VALUES
	('tournament_published', 'Tournament Published', 'Your tournament "{{tournament_name}}" is live', '<p>Hi {{first_name}},</p><p>Great news — <strong>{{tournament_name}}</strong> has been approved and is now open for registration.</p><p><a href="{{link}}">View your tournament</a></p>{{sponsor_logos}}', '{first_name,tournament_name,event_date,link}', true, '2026-06-15 19:51:22.755766+00', NULL),
	('tournament_rejected', 'Tournament Returned for Changes', 'Changes needed on "{{tournament_name}}"', '<p>Hi {{first_name}},</p><p>Your tournament <strong>{{tournament_name}}</strong> was returned for changes.</p><p>Reason: {{reason}}</p><p><a href="{{link}}">Edit and resubmit</a></p>', '{first_name,tournament_name,reason,link}', true, '2026-06-15 19:51:22.755766+00', NULL),
	('tournament_cancelled', 'Tournament Cancelled', '"{{tournament_name}}" has been cancelled', '<p>Hi {{first_name}},</p><p>We''re sorry to let you know that <strong>{{tournament_name}}</strong> has been cancelled.</p>{{sponsor_logos}}', '{first_name,tournament_name}', true, '2026-06-15 19:51:22.755766+00', NULL),
	('tournament_pending', 'Tournament Awaiting Approval', 'A tournament needs review: {{tournament_name}}', '<p>Hi {{first_name}},</p><p><strong>{{tournament_name}}</strong> by {{director_name}} is awaiting your approval.</p><p><a href="{{link}}">Review it</a></p>', '{first_name,tournament_name,director_name,link}', true, '2026-06-15 19:51:22.755766+00', NULL),
	('director_approved', 'Director Approved', 'You''re an approved director on DreamBreaker', '<p>Hi {{first_name}},</p><p>Your director account has been approved. You can now create and manage tournaments.</p><p><a href="{{link}}">Go to your dashboard</a></p>{{sponsor_logos}}', '{first_name,link}', true, '2026-06-15 19:51:22.755766+00', NULL),
	('director_suspended', 'Director Access Suspended', 'Your director access has been suspended', '<p>Hi {{first_name}},</p><p>Your director access has been suspended. Please contact support if you believe this is a mistake.</p>', '{first_name}', true, '2026-06-15 19:51:22.755766+00', NULL),
	('registration_confirmed', 'Registration Confirmed', 'You''re registered for "{{tournament_name}}"', '<p>Hi {{first_name}},</p><p>Your spot in <strong>{{tournament_name}}</strong> on {{event_date}} is confirmed. See you on the court!</p><p><a href="{{link}}">View details</a></p>{{sponsor_logos}}', '{first_name,tournament_name,event_date,link}', true, '2026-06-15 19:51:22.755766+00', NULL),
	('payment_receipt', 'Payment Receipt', 'Receipt for "{{tournament_name}}" — {{amount}}', '<p>Hi {{first_name}},</p><p>Thanks for your payment. Here is your receipt:</p><p><strong>{{tournament_name}}</strong><br/>Date: {{event_date}}<br/>Amount paid: <strong>{{amount}}</strong></p><p><a href="{{link}}">View registration</a></p><p>Keep this email for your records.</p>', '{first_name,tournament_name,event_date,amount,link}', true, '2026-06-16 03:12:44.545551+00', NULL),
	('refund_processed', 'Refund Processed', 'Your refund for "{{tournament_name}}" is on its way', '<p>Hi {{first_name}},</p><p>We''ve processed a refund of <strong>{{amount}}</strong> for <strong>{{tournament_name}}</strong>.</p><p>Refunds typically take 5–10 business days to appear on your statement, depending on your bank.</p>', '{first_name,tournament_name,amount}', true, '2026-06-16 03:12:44.545551+00', NULL),
	('waitlist_added', 'Added to Waitlist', 'You''re on the waitlist for "{{tournament_name}}"', '<p>Hi {{first_name}},</p><p><strong>{{tournament_name}}</strong> is currently full, so we''ve added you to the waitlist at <strong>position {{position}}</strong>.</p><p>We''ll email you the moment a spot opens up. No action needed for now.</p><p><a href="{{link}}">View tournament</a></p>{{sponsor_logos}}', '{first_name,tournament_name,position,link}', true, '2026-06-16 03:12:44.545551+00', NULL),
	('waitlist_promoted', 'Waitlist Spot Available', 'A spot opened up in "{{tournament_name}}"', '<p>Hi {{first_name}},</p><p>Good news — a spot just opened in <strong>{{tournament_name}}</strong> and it''s yours to claim.</p><p>Please complete your registration by <strong>{{deadline}}</strong> or the spot moves to the next player.</p><p><a href="{{link}}">Claim your spot</a></p>{{sponsor_logos}}', '{first_name,tournament_name,deadline,link}', true, '2026-06-16 03:12:44.545551+00', NULL),
	('event_reminder', 'Event Reminder', 'Reminder: "{{tournament_name}}" is on {{event_date}}', '<p>Hi {{first_name}},</p><p>Just a reminder that <strong>{{tournament_name}}</strong> is coming up on <strong>{{event_date}}</strong>.</p><p>Venue: {{venue_name}}</p><p>Make sure your paddle is ready and arrive early for check-in.</p><p><a href="{{link}}">View details</a></p>{{sponsor_logos}}', '{first_name,tournament_name,event_date,venue_name,link}', true, '2026-06-16 03:12:44.545551+00', NULL),
	('checkin_open', 'Check-In Open', 'Check-in is open for "{{tournament_name}}"', '<p>Hi {{first_name}},</p><p>Check-in is now open for <strong>{{tournament_name}}</strong>. Please check in to confirm your spot in the draw.</p><p><a href="{{link}}">Check in now</a></p>{{sponsor_logos}}', '{first_name,tournament_name,link}', true, '2026-06-16 03:12:44.545551+00', NULL),
	('new_match', 'New Partner Match', 'You matched with {{match_name}} on DreamBreaker', '<p>Hi {{first_name}},</p><p>You and <strong>{{match_name}}</strong> both liked each other — you''re a match! Start a conversation and find your next tournament partner.</p><p><a href="{{link}}">Say hello</a></p>{{sponsor_logos}}', '{first_name,match_name,link}', true, '2026-06-16 03:12:44.545551+00', NULL),
	('results_ready', 'Results Are In', 'Results for "{{tournament_name}}" are in', '<p>Hi {{first_name}},</p><p>The results for <strong>{{tournament_name}}</strong> are in. You finished <strong>{{placement}}</strong>. Nice work out there!</p><p><a href="{{link}}">See full standings</a></p>{{sponsor_logos}}', '{first_name,tournament_name,placement,link}', true, '2026-06-16 03:12:44.545551+00', NULL);
